 useEffect(()=>{if(localStorage.getItem('ent-language')==='kk')setLang('kk');void refresh();const sync=()=>{const s=location.hash.slice(1) as Screen;if(navigation.some(n=>n[0]===s)||['settings','visuals','lesson','diagnostic'].includes(s))setScreen(s);};sync();window.addEventListener('hashchange',sync);return()=>window.removeEventListener('hashchange',sync);},[]);
 useEffect(()=>{if(!loading&&location.hash==='#lesson'&&state?.lessonResume){setTopicId(state.lessonResume.topicId);setLessonStep(state.lessonResume.stage);}},[loading]);
 useEffect(()=>{if(!onboard&&!menu)return;const selector=onboard?'.onboard-modal':'.sidebar';const dialog=document.querySelector<HTMLElement>(selector);if(!dialog)return;const previous=document.activeElement as HTMLElement|null;const focusable=()=>Array.from(dialog.querySelectorAll<HTMLElement>('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')).filter(e=>e.getClientRects().length>0);const first=focusable()[0];first?.focus();const listener=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();onboard?setOnboard(false):setMenu(false);}if(event.key==='Tab'){const items=focusable(),start=items[0],end=items.at(-1);if(!start)return;if(event.shiftKey&&document.activeElement===start){event.preventDefault();end?.focus();}else if(!event.shiftKey&&document.activeElement===end){event.preventDefault();start.focus();}}};document.addEventListener('keydown',listener);return()=>{document.removeEventListener('keydown',listener);previous?.focus();};},[onboard,menu]);
