 const loadPractice=async(id?:string,review?:string)=>{const t=curriculum.find(t=>t.id===id)??topic;setTopicId(t.id);const dueReview=review&&state?.reviews?.find((r:Data)=>r.id===review&&!r.completed&&new Date(r.due).getTime()<=Date.now());setReviewId(dueReview?review:undefined);setFeedback(null);setAnswer('');setSteps('');setHint(0);setTaskIndex(0);navigate('practice');setBusy(true);try{const d=await api(`/api/tasks?topic=${t.id}${dueReview?`&reviewId=${encodeURIComponent(review!)}`:''}`);const list:Array<Data>=(Array.isArray(d)?d:d.tasks??[]).filter((task:Data)=>dueReview||!task.reviewReserved);const used=new Set(attempts.map((a:Data)=>a.taskId));setTasks([...list.filter(t=>!used.has(t.id)&&!t.modelExample),...list.filter(t=>!used.has(t.id)&&t.modelExample),...list.filter(t=>used.has(t.id))]);}catch(e){setNotice((e as Error).message);}finally{setBusy(false);}};
