 {screen==='analytics'&&<><div className="page-heading"><div><h1>{tr('Твой прогресс в деталях','Сенің нәтижең толық')}</h1><p>{tr('Просмотр урока не равен освоению. Считаем самостоятельные решения.','Сабақты көру меңгеруге тең емес. Өздік шешімдерді есептейміз.')}</p></div><button className="secondary" onClick={()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({profile:state?.profile,progress,attempts,exams:state?.exams},null,2)],{type:'application/json'}));a.download='ent-math-progress.json';a.click();URL.revokeObjectURL(a.href);}}><Download size={17}/>{tr('Скачать','Жүктеу')}</button></div><div className="analytics-stats">{[[tracks[track][lang],trackAttempts.length],[tr('Самостоятельно верно','Өз бетімен дұрыс'),trackAttempts.filter((a:Data)=>a.correct&&!a.assisted).length],[tr('Освоено тем','Меңгерілген тақырыптар'),trackMastered],[tr('Игровой уровень','Ойын деңгейі'),Math.floor((state?.xp??0)/250)+1]].map(([l,v])=><div className="panel" key={l}><small>{l}</small><strong>{v}</strong></div>)}</div><section className="panel progress-by-topic"><h2>{tr('Навыки по направлениям','Бағыттар бойынша дағдылар')}</h2><div className="track-tabs">{(Object.keys(tracks) as (keyof typeof tracks)[]).map(t=><button aria-pressed={track===t} className={track===t?'selected':''} key={t} onClick={()=>changeTrack(t)}>{tracks[t][lang]}</button>)}</div>{filtered.map(t=><button className="skill-row" key={t.id} onClick={()=>openLesson(t.id)}><span>{t.title[lang]}</span><div className="progress-track"><span style={{width:`${percent(t.id)}%`}}/></div><strong>{percent(t.id)}%</strong><span className="muted">{progress[t.id]?.mastered?tr('Освоено','Меңгерілді'):progress[t.id]?.independent?tr('Закрепляем','Бекітеміз'):tr('Начать','Бастау')}</span><ChevronRight size={16}/></button>)}</section></>}
 {screen==='achievements'&&<><div className="page-heading"><div><h1>{tr('Твои маленькие победы','Сенің кішкентай жеңістерің')}</h1><p>{tr('Опыт мотивирует. Освоение показывает, что ты умеешь.','Тәжірибе ынталандырады. Меңгеру не істей алатыныңды көрсетеді.')}</p></div></div><div className="level-panel"><span className="achievement-icon"><Trophy size={35}/></span><div><small>{tr('Игровой уровень','Ойын деңгейі')}</small><h2>{Math.floor((state?.xp??0)/250)+1} · {tr('Исследователь','Зерттеуші')}</h2><p>{state?.xp??0} XP · {250-(state?.xp??0)%250} {tr('до следующего уровня','келесі деңгейге дейін')}</p></div><div className="level-mastery"><strong>{mastered}</strong><span>{tr('тем освоено','тақырып меңгерілді')}</span></div></div><div className="achievement-grid">{[{title:tr('Первый шаг','Алғашқы қадам'),text:tr('Заверши диагностику','Диагностиканы аяқта'),done:state?.diagnostics?.length>0,Icon:Target},{title:tr('Сам себе помощник','Өзіңе көмекші'),text:tr('Реши 3 новые задачи без подсказок','3 жаңа есепті кеңессіз шеш'),done:Object.values(progress).reduce((sum:number,p:any)=>sum+(p.independent??0),0)>=3,Icon:PenLine},{title:tr('Ошибка в прошлом','Қате артта қалды'),text:tr('Реши задачу при повторении','Қайталауда есепті шеш'),done:state?.reviews?.some((r:Data)=>r.completed),Icon:RotateCcw},{title:tr('Крепкий фундамент','Берік негіз'),text:tr('Подтверди освоение первой темы','Алғашқы тақырыпты меңгеруді раста'),done:mastered>0,Icon:BookOpen},{title:tr('Готов к формату','Форматқа дайын'),text:tr('Заверши пробный экзамен','Сынақ емтиханын аяқта'),done:state?.exams?.length>0,Icon:ClipboardCheck},{title:tr('Возвращение к сложному','Қиынға қайта оралу'),text:tr('Продолжи после нескольких ошибок','Бірнеше қатеден кейін жалғастыр'),done:attempts.length>=5&&state?.errors?.length>0,Icon:Flame}].map(a=><article className={`panel achievement-card ${a.done?'unlocked':'locked'}`} key={a.title}><span className="achievement-icon"><a.Icon size={30}/></span><h3>{a.title}</h3><p>{a.text}</p><span className="small-chip">{a.done?<Check size={13}/>:<LockKeyhole size={13}/>} {a.done?tr('Получено','Алынды'):tr('Впереди','Алда')}</span></article>)}</div></>}
